files.nginx.conf:
# Internal HTTP listener. Terminate TLS and enforce HTTPS/HSTS at the trusted edge.
worker_processes 1;
pid /tmp/nginx.pid;
error_log /dev/stderr crit;
events { worker_connections 256; }
http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    server_tokens off;
    gzip on;
    gzip_vary on;
    gzip_min_length 256;
    gzip_comp_level 6;
    gzip_types text/css text/javascript application/javascript application/json;
    client_body_temp_path /tmp/client_body;
    proxy_temp_path /tmp/proxy;
    fastcgi_temp_path /tmp/fastcgi;
    uwsgi_temp_path /tmp/uwsgi;
    scgi_temp_path /tmp/scgi;
    log_format nexo_json escape=json '{"status":$status,"bytes":$body_bytes_sent,"duration":$request_time,"method":"$request_method"}';
    access_log /dev/stdout nexo_json;
    limit_req_zone $binary_remote_addr zone=static_rate:10m rate=20r/s;
    map $uri $nexo_cache {
        default "no-store";
        /index.html "no-cache";
        ~^/assets/ "public, max-age=31536000, immutable";
    }
    server {
        listen 8080;
        server_name _;
        root /srv/nexo;
        index index.html;
        client_max_body_size 64k;
        limit_req zone=static_rate burst=40 nodelay;
        limit_req_status 429;
        add_header Cache-Control $nexo_cache always;
        add_header Content-Security-Policy "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'" always;
        add_header X-Content-Type-Options nosniff always;
        add_header Referrer-Policy no-referrer always;
        add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
        location = /healthz { access_log off; default_type text/plain; return 200 "ok\n"; }
        location ~ /\. { deny all; }
        location / {
            limit_except GET { deny all; }
            try_files $uri $uri/ =404;
        }
    }
}

example.source:
use nexo.web

pub component App:
    state count: int = 0

    fn increment():
        count += 1

    view:
        main:
            h1("Nexo Web release")
            p("Count: {count}", role: "status")
            button("Increment", on_click: increment)

    style:
        main {
            max-width: 48rem;
            margin: 2rem auto;
            padding: 1rem;
            color: #172033;
            background: #ffffff;
            font: 1.1rem/1.5 system-ui;
        }
        button { padding: 0.7rem 1rem; color: #ffffff; background: #0d47a1; border: 0; border-radius: 0.4rem; font: inherit; }
        button:focus-visible { outline: 3px solid #0d47a1; outline-offset: 4px; }
